#include "emitter59_internal.h"
/* $06293E: attached repeat emitter; children publish their heartbeat to $21. */
static void tick(struct EntityPool*,struct NativeEntity*,void*);
void e59_schedule(struct NativeEntity*e,unsigned s){e->tick=tick;enemy_schedule(&e->payload.enemy,s);}
struct NativeEntity*e59_allocate(struct WeaponWorld*w,struct EntityRef parent,enum EntityInsert order,const struct PlayerTransform*t,unsigned s){struct NativeEntity*n=enemy_allocate(w,parent,order,t,tick);if(n){uint8_t*b=(uint8_t*)&n->payload.enemy.emitter59;for(unsigned i=0;i<sizeof(n->payload.enemy.emitter59);i++)b[i]=255;n->payload.enemy.selector=n->payload.enemy.scale=65535;n->payload.enemy.emitter59.release_valid=0;e59_schedule(n,s);}return n;}
struct NativeEntity*e59_child(struct WeaponWorld*w,struct NativeEntity*e,unsigned s){return e59_allocate(w,entity_ref(e),ENTITY_FIRST_CHILD,&e->payload.enemy.actor.transform,s);}
void e59_entry(struct EnemyActor*q,uint16_t n){if(n!=65535){animation_begin(&q->actor.animation,n);q->actor.movement_flags|=32;}}
void e59_start(struct EnemyActor*q,unsigned n){e59_entry(q,emitter59_entries[n]);}
void e59_defense(struct EnemyActor*q,unsigned n){q->actor.defense=n==65535?0:emitter59_bindings[n].defense;q->actor.defense_count=n==65535?0:emitter59_bindings[n].count;}
void e59_attack(struct EnemyActor*q,unsigned n){if(n==65535)q->actor.attack=0;else{q->attack_set=(struct HitAttackSet){emitter59_bindings[n].attack,emitter59_bindings[n].count};q->actor.attack=&q->attack_set;}}
int16_t e59_rank(struct WeaponWorld*w,struct EnemyActor*q,unsigned n){struct InteractionWorld*r=w->interactions;if(!r||!r->rank_valid||n>=E59R_COUNT){enemy_fault(w);return 0;}unsigned i=(interaction_rank(w,&q->actor,runtime_owner_emitter59[n]))*8+(q->source_flags&3)*2;const struct Emitter59RankData*t=&emitter59_rank[n];if(t->choices)i=t->choices[i+((uint8_t)(r->player_count_flag-1)&1)]*8+((tk_random(w)&14)>>1);else i+=(r->player_count_flag&2)>>1;return (int16_t)t->values[i];}
struct Context{struct WeaponWorld*w;struct NativeEntity*e;};
static uint32_t read(void*ctx,unsigned f,unsigned width){(void)width;struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;if(f==E59F_7C_2)return (uint16_t)q->emitter59.angle;if(f==E59F_34_2)return q->selector;if(f==E59F_2E_2)return (uint16_t)q->actor.ay;enemy_fault(c->w);return 0;}
static int field(void*ctx,unsigned f,unsigned width,enum AnimationFieldOperation op,uint32_t v){struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;uint32_t old=read(ctx,f,width);if(op==AN_FIELD_AND)v&=old;else if(op==AN_FIELD_OR)v|=old;else if(op==AN_FIELD_XOR)v^=old;else if(op!=AN_FIELD_SET)return enemy_fault(c->w);if(f==E59F_7C_2)q->emitter59.angle=v;else if(f==E59F_34_2)q->selector=v;else if(f==E59F_2E_2)q->actor.ay=v;else return enemy_fault(c->w);return !c->w->fault;}
static int bind(void*ctx,unsigned k,uint32_t v){struct Context*c=ctx;unsigned n=v==0xffffffffu?65535:v;if(n!=65535&&n>=6)return enemy_fault(c->w);if(k==AN_DEFENSE)e59_defense(&c->e->payload.enemy,n);else if(k==AN_ATTACK)e59_attack(&c->e->payload.enemy,n);else return enemy_fault(c->w);return 1;}
static int sound(void*ctx,uint16_t n,int stop){struct Context*c=ctx;return c->w->sound&&c->w->sound(c->w->scene,n,stop)?1:enemy_fault(c->w);}
static int call(void*ctx,unsigned n,struct Animation*an){(void)an;struct Context*c=ctx;if(n==E59C_283CA){hit_begin_attack(&c->e->payload.enemy.actor.hit);return 1;}return e59_emit(c->w,c->e,n);}
int e59_animate(struct WeaponWorld*w,struct NativeEntity*e){struct WeaponActor*a=&e->payload.enemy.actor;if(a->animation.cursor==65535)return 0;struct Context c={w,e};struct AnimationOwner o={.context=&c,.read=read,.write=field,.bind=bind,.sound=sound,.call=call};int done=animation_step(&a->animation,&emitter59_program,&o);if(a->animation.fault)enemy_fault(w);return done;}
int e59_outside(struct WeaponWorld*w,struct WeaponActor*a,unsigned i,int force){static const int16_t b[]={0,1,0,1};return interaction_outside(w,a,i<2?emitter59_bounds[i]:b,force);}
static int phase(struct WeaponWorld*w,struct NativeEntity*e,uint8_t*out){struct NativeEntity*p=entity_get(w->entities,e->parent);if(!p){enemy_fault(w);return 0;}if(p->kind==ENTITY_GROUP)*out=p->payload.group.phase;else{struct WeaponActor*a=entity_weapon_actor(p);if(!a){enemy_fault(w);return 0;}*out=a->phase;}return 1;}
static int heartbeat(struct WeaponWorld*w,struct NativeEntity*e){struct NativeEntity*p=entity_get(w->entities,e->parent);if(!p||p->kind!=ENTITY_ENEMY)return enemy_fault(w);p->payload.enemy.dead=1;return 1;}
static int in_range(struct WeaponWorld*w,struct WeaponActor*a){return tk_sx(w,a)>=16&&tk_sx(w,a)<=272;}
static int target_angle(struct WeaponWorld*w,struct WeaponActor*a){int i=enemy_nearest_x(w,a,0);if(i<0)return -1;int16_t dx=tk_faced(a,tk_word((a->transform.x-w->players[i]->actor.transform.x)>>8));return dx>96?0:dx>0?1:dx>-96?2:3;}
static int tail(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;uint8_t p;if(!heartbeat(w,e)||!tk_hit_sound(w,a))return 0;if(a->hit.flags&8){a->hit.flags&=247;q->emitter59.hurt=10;}q->emitter59.hurt--;if((int8_t)q->emitter59.hurt<=0)q->emitter59.hurt=0;if(q->emitter59.hurt){q->emitter59.shake++;transform_integer_offset(&a->transform,0,emitter59_shake[q->emitter59.shake&3]);}if(q->emitter59.locked){if(!phase(w,e,&p))return 0;if(p==255)e59_schedule(e,E59_RELEASE);}if(a->hit.flags&1)e59_schedule(e,E59_DEAD);if(e59_outside(w,a,0,1))e59_schedule(e,E59_DELETE_TREE);return !w->fault;}
static int enter(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;struct NativeEntity*n;uint8_t p;
 switch(a->state){
 case E59_ROOT:n=e59_child(w,e,E59_WAIT);if(!n)return 0;n->payload.enemy.emitter59.locked=1;q->dead=1;q->emitter59.count=e59_rank(w,q,E59R_COUNT0+(q->params[0]&3));q->emitter59.timer=45;break;
 case E59_WAIT:a->phase=0;break;
 case E59_BODY:a->display_flags|=2;a->palette=0x6d;a->hit_palette=0x79;a->hit.hp=e59_rank(w,q,E59R_HP);q->emitter59.wait=tk_word(e59_rank(w,q,E59R_WAIT)+(tk_random(w)&31));q->emitter59.releases=(tk_random(w)&1)+2;a->transform.priority=0x100;q->emitter59.angle=2;a->vx=24;a->vy=288;q->emitter59.timer=88;if(!phase(w,e,&p))return 0;if(p==255){a->vx=56;a->vy=384;q->emitter59.timer=48;}q->emitter59.hurt=q->emitter59.shake=q->emitter59.sound_started=0;e59_start(q,E59A_INTRO);a->state=E59_INTRO;break;
 case E59_OPEN:if(!w->sound||!w->sound(w->scene,0x1071,1))return enemy_fault(w);e59_defense(q,E59B_BODY);m4_reset(a);e59_start(q,E59A_OPEN);break;
 case E59_IDLE:q->emitter59.angle&=3;e59_start(q,E59A_IDLE);break;
 case E59_TURN:q->selector=(q->emitter59.angle*2)&7;q->emitter59.timer=0;q->emitter59.turns=0;e59_start(q,E59A_TURN);break;
 case E59_FIRE_NEW:q->emitter59.repeats=e59_rank(w,q,E59R_BURST);/* FALLTHROUGH */
 case E59_FIRE_REPEAT:if(!in_range(w,a)){e59_schedule(e,E59_IDLE);return 2;}q->emitter59.wait=e59_rank(w,q,E59R_FIRE_WAIT);q->emitter59.angle&=3;e59_entry(q,(q->emitter59.repeats>=1&&q->emitter59.wait<45?emitter59_fast_fire:emitter59_fire)[q->emitter59.angle]);a->state=E59_FIRE;break;
 case E59_RELEASE:if(!tk_sound(w,0x1020))return 0;m4_reset(a);e59_start(q,E59A_RELEASE);break;
 case E59_FALL:a->transform.priority=0x8000;m4_reset(a);transform_integer_offset(&a->transform,0,-32);e59_start(q,E59A_FALL);break;
 case E59_LANDED:e59_start(q,E59A_LANDED);break;
 case E59_DEAD:a->display_flags&=253;m4_reset(a);e59_start(q,E59A_DEAD);break;
 default:return enemy_fault(w);
 }return !w->fault;
}
static int frame(struct WeaponWorld*w,struct NativeEntity*e,unsigned s){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;uint8_t p;int r,done;
 if(s==E59_ROOT){if(interaction_move(w,a,WMOVE_SYNC)<0||!phase(w,e,&p))return 0;a->phase=p;if(!q->dead){q->emitter59.timer=tk_word(q->emitter59.timer-1);if(q->emitter59.timer<=0){q->emitter59.count=tk_word(q->emitter59.count-1);if(q->emitter59.count<0){entity_delete(w->entities,e);return 0;}q->emitter59.timer=45;struct NativeEntity*n=e59_child(w,e,E59_WAIT);if(!n)return 0;n->payload.enemy.emitter59.locked=p!=255;}}q->dead=0;if(e59_outside(w,a,0,0))e59_schedule(e,E59_DELETE_TREE);return !w->fault;}
 if(s==E59_WAIT){if(!phase(w,e,&p))return 0;if(p==255)q->emitter59.locked=0;if(!heartbeat(w,e))return 0;if(tk_sx(w,a)<=32){entity_delete_children(w->entities,e);entity_delete(w->entities,e);return 0;}if(tk_sx(w,a)<=272){e59_schedule(e,E59_BODY);return 2;}return interaction_move(w,a,WMOVE_SYNC)>=0;}
 if(s==E59_INTRO){if(!q->emitter59.sound_started&&(uint16_t)q->emitter59.timer<48){if(!tk_sound(w,0x1071))return 0;q->emitter59.sound_started=1;}if(!(w->frame_phase&1)){struct NativeEntity*n=e59_child(w,e,E59_PUFF);if(!n)return 0;transform_integer_offset(&n->payload.enemy.actor.transform,0,24);}int flip=!(w->frame_phase&3);if(flip)a->vy=tk_word(-a->vy);r=interaction_move(w,a,WMOVE_POINT);if(flip)a->vy=tk_word(-a->vy);if(r<0)return 0;e59_animate(w,e);q->emitter59.timer=tk_word(q->emitter59.timer-1);if(q->emitter59.timer<=0)e59_schedule(e,E59_OPEN);return heartbeat(w,e);}
 if(s==E59_RELEASE||s==E59_FALL||s==E59_DEAD){if(!heartbeat(w,e))return 0;r=interaction_move(w,a,s==E59_FALL?WMOVE_BODY:WMOVE_SYNC);if(r<0)return 0;if(s==E59_FALL&&r)e59_schedule(e,E59_LANDED);done=e59_animate(w,e);if(s==E59_RELEASE&&done)e59_schedule(e,E59_FALL);if(s==E59_DEAD&&done)e59_schedule(e,E59_DELETE_TREE);if(s==E59_FALL){hit_begin_attack(&a->hit);if(!enemy_attack(w,a))return 0;if(a->hit.flags&2)e59_schedule(e,E59_DEAD);}if(e59_outside(w,a,0,1))e59_schedule(e,E59_DELETE_TREE);return !w->fault;}
 if(interaction_move(w,a,WMOVE_SYNC)<0)return 0;
 if(s==E59_LANDED){if(e59_animate(w,e))a->display_flags&=253;if(e59_outside(w,a,0,1))e59_schedule(e,E59_DELETE_TREE);return !w->fault;}
 if(s==E59_OPEN){if(e59_animate(w,e))e59_schedule(e,E59_IDLE);}
 else if(s==E59_IDLE){e59_animate(w,e);q->emitter59.wait=tk_word(q->emitter59.wait-1);if(q->emitter59.wait<=0){int angle=target_angle(w,a);if(angle>=0){if(angle!=q->emitter59.angle){q->emitter59.direction=angle>q->emitter59.angle?1:-1;e59_schedule(e,E59_TURN);}else if(in_range(w,a))e59_schedule(e,E59_FIRE_NEW);}}}
 else if(s==E59_TURN){q->emitter59.timer=tk_word(q->emitter59.timer-1);if(q->emitter59.timer<=0){q->emitter59.turns++;if(q->emitter59.turns==3){e59_schedule(e,E59_IDLE);return 2;}q->emitter59.timer=e59_rank(w,q,E59R_TURN);q->selector=(q->selector+q->emitter59.direction)&7;q->emitter59.angle=q->selector>>1;}e59_animate(w,e);}
 else if(s==E59_FIRE){q->emitter59.wait=tk_word(q->emitter59.wait-1);if(q->emitter59.wait>0)a->animation.freeze=1;if(e59_animate(w,e)){e59_schedule(e,E59_FIRE_REPEAT);q->emitter59.repeats=tk_word(q->emitter59.repeats-1);if(q->emitter59.repeats<=0){q->emitter59.wait=tk_word(e59_rank(w,q,E59R_WAIT)+(tk_random(w)&31));e59_schedule(e,E59_IDLE);}}}
 else return enemy_fault(w);return tail(w,e);
}
static void tick(struct EntityPool*p,struct NativeEntity*e,void*world){struct WeaponWorld*w=world;if(w->fault)return;struct EnemyActor*q=&e->payload.enemy;for(unsigned b=0;b<12;b++){unsigned s=q->actor.state;if(s==E59_DELETE||s==E59_DELETE_TREE){if(s==E59_DELETE_TREE)entity_delete_children(p,e);entity_delete(p,e);return;}if(q->entry){q->entry=0;int r=s<E59_SHELL?enter(w,e):e59_fx_enter(w,e);if(!r||w->fault)return;if(r==2)continue;}if(!e->active||e->deleting)return;s=q->actor.state;int r=s<E59_SHELL?frame(w,e,s):e59_fx_frame(w,e,s);if(r==2)continue;return;}enemy_fault(w);}
int emitter59_spawn(struct WeaponWorld*w,struct EntityRef p,enum EntityInsert o,const struct PlayerTransform*t,const uint8_t params[8]){struct NativeEntity*e=e59_allocate(w,p,o,t,E59_ROOT);if(!e)return 0;if(params)for(unsigned i=0;i<8;i++)e->payload.enemy.params[i]=params[i];return 1;}
